    '{"yea":53,"nay":43,"present":0,"notVoting":4,"byParty":{"D":{"yea":8,"nay":36},"R":{"yea":44,"nay":6},"I":{"yea":1,"nay":1}}}'::jsonb, 'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00563.htm', 'U.S. Senate')
  ON CONFLICT (chamber, congress, session, roll_number) DO NOTHING;
  SELECT id INTO rc FROM vr_rollcalls
   WHERE chamber = 'senate' AND congress = 119 AND session = 1 AND roll_number = 563 LIMIT 1;
