  -- ── issue mappings ────────────────────────────────────────────────────────
  -- Curated in db/vr-issue-seed.json, with the rationale and a primary source on every row
  -- — scripts/test-mapping-discipline.mjs requires both — and argued in
  -- db/vr-federal-mapping-seed-f1.json, which also records every refusal. ON CONFLICT
  -- (measure_id, issue_key) DO NOTHING, so a re-emission cannot rewrite a rationale.

  -- H.J.Res. 25 (119th) — gov_regulation yea_supports w100 PRIMARY, tech_innovation yea_supports w60
  --   ALREADY LIVE. This pass adds no mapping to this measure and changes none: the rows
  --   below are the ones already on the row, re-stated so the migration is a complete
  --   description of what the measure carries once its roll calls land. ON CONFLICT DO
  --   NOTHING means every one is a no-op, and the live rationale stays the first writer's
  --   (runbook rule 21). What this pass gives the measure is the votes, not the reading.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_j_res_25, 'gov_regulation', 100, true, 'yea_supports',
      'Congressional Review Act resolution repealing the IRS reporting rule for decentralized-finance brokers; a yea rolls back the mandate.',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/25'),
    (m_119_h_j_res_25, 'tech_innovation', 60, false, 'yea_supports',
      'Nullifies the IRS rule that extended broker tax-reporting duties to decentralized-finance platforms, so those platforms are not required to collect and report user transaction data. A yea removes that reporting duty from decentralized software. Enacted as Public Law 119-5.',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/25')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- S.J.Res. 18 (119th) — gov_regulation yea_supports w100 PRIMARY, econ_corp_account yea_opposes w75 PRIMARY
  --   ALREADY LIVE. This pass adds no mapping to this measure and changes none: the rows
  --   below are the ones already on the row, re-stated so the migration is a complete
  --   description of what the measure carries once its roll calls land. ON CONFLICT DO
  --   NOTHING means every one is a no-op, and the live rationale stays the first writer's
  --   (runbook rule 21). What this pass gives the measure is the votes, not the reading.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_j_res_18, 'gov_regulation', 100, true, 'yea_supports',
      'A Congressional Review Act resolution whose entire operative effect is to nullify a federal rule; a yea strikes the CFPB overdraft regulation off the books.',
      'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/18'),
    (m_119_s_j_res_18, 'econ_corp_account', 75, true, 'yea_opposes',
      'The nullified rule required very large financial institutions to cap overdraft charges at $5, justify a higher cap, or treat overdrafts as credit subject to Truth in Lending Act disclosure; a yea removes that constraint on what the largest banks may charge. Primary: what the largest banks may charge their customers is the resolution''s own subject — the rule it nullifies is that rule and no other — not a by-product of a broader vehicle. Weighted 75 rather than 100 because the Congressional Review Act framing carries the larger share and outranks it; the weight is what ranks the two axes.',
      'https://www.congress.gov/bill/119th-congress/senate-joint-resolution/18')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 1069 (119th): NO MAPPING, and that is the decision rather than a gap.
  --   MAPPINGS REFUSED — nine candidates read, nine refused. Ships unmapped, on purpose.
  --   Every candidate key is refused in writing in db/vr-federal-mapping-seed-f1.json, and
  --   the verification block below asserts this measure carries zero mapped rows. A
  --   mapping is never invented at generation time, and a measure the record has decided
  --   to leave unmapped is not quietly mapped by the next pass that touches it.

  -- S.Amdt. 3535 (119th) — congress_oversight yea_supports w100 PRIMARY, audit_spending yea_supports w70
  --   Mapped from the Senate's own complete amendment_purpose field, which clears runbook
  --   rule 4 (a truncated purpose line is not a mappable purpose). The amendment rode the
  --   FY2026 NDAA because that is where floor time was, so the parent's strong_defense is
  --   NOT inherited — see db/vr-federal-mapping-seed-f1.json for that refusal and for why
  --   checks_balances is refused under rule 28 and on a two-way reading of Presidential
  --   appointment.
  --   Read and refused on this measure: checks_balances, gov_transparency, strong_defense,
  --   econ_corp_account, gov_waste. The argument against each is in
  --   db/vr-federal-mapping-seed-f1.json.
  --   BACKWARDS READ (rule 22), congress_oversight: A NAY on S.Amdt. 3535 is honestly
  --   described as opposition to 'Make the executive branch answer congressional
  --   subpoenas, document requests and testimony.' TRUE at the level of the mechanism —
  --   the nays voted to leave the IG appointed inside the agency rather than confirmed by
  --   the Senate — and the chip's named instruments (subpoenas, testimony) are narrower
  --   than the amendment, which is why the rationale rests on the keyword the key itself
  --   carries.
  --   BACKWARDS READ (rule 22), audit_spending: A NAY is honestly described as opposition
  --   to 'Audit federal agencies and the Federal Reserve'. Reads TRUE but narrowly — the
  --   nays did not vote against auditing the Fed, they voted against this appointment
  --   route to its auditor. Recorded at 70 for that reason.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_s_amdt_3535, 'congress_oversight', 100, true, 'yea_supports',
      'The amendment''s stated purpose is its entire substance: to require Presidential appointment and Senate confirmation of the inspector general of the Federal Reserve Board of Governors and of the Consumer Financial Protection Bureau. Under current law that inspector general is designated by the Fed Chair, so a yea moves the watchdog of both bodies out of agency appointment and into advice and consent, giving the Senate a hold on an oversight officer it has none over today. congress_oversight''s keyword list names ''inspector general'' explicitly, which is the vocabulary''s own statement that IG machinery belongs on this axis. Primary at 100 as the amendment''s only subject; the record''s one prior row on this key is a 45-weight secondary on H.R. 7888, a package — which is exactly why the formal index could not read the axis for five of the seven Utah federal members. The counter-reading is real and is recorded next door: the 36 Democratic nays argued that confirmation politicises the watchdog of an independent central bank. That is an argument about how much political control the post should carry, which is this axis; the executive-power half of it is why checks_balances is refused.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00563.htm'),
    (m_119_s_amdt_3535, 'audit_spending', 70, false, 'yea_supports',
      'The office the amendment reshapes is the internal auditor of the Federal Reserve and the CFPB, and audit_spending is ''Audit federal agencies and the Federal Reserve and root out wasteful spending'' — the only chip in the vocabulary that names the Federal Reserve at all, with keywords ''audit the fed'' and ''federal reserve''. A yea subjects that auditor to Senate confirmation. Weighted 70 rather than 100 because the amendment changes who appoints the auditor and not what the auditor may examine: it adds no audit authority, so the row is a share of the key and not the whole of it. Above the record''s two existing rows on this key (both 55, both secondaries) because those are provisions inside larger bills and this is the amendment''s entire text.',
      'https://www.senate.gov/legislative/LIS/roll_call_votes/vote1191/vote_119_1_00563.htm')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.J.Res. 131 (119th) — lands_energy yea_supports w100 PRIMARY, lands_preserve yea_opposes w90, energy_production yea_supports w75, gov_regulation yea_supports w60
  --   A CRA disapproval that deliberately does NOT carry climate_action, unlike the two
  --   live CRA precedents H.J.Res. 88 and H.J.Res. 89. Those struck Clean Air Act vehicle
  --   waivers, where greenhouse gases were the whole subject of the rule; this one strikes
  --   a Record of Decision about which acres of a leasing programme are available, and
  --   emissions appear nowhere in it. energy_production carries the fossil-expansion
  --   reading in a direction nobody on the roll disputes. Runbook rule 25: consistency is
  --   owed to the text, not to the sibling.
  --   Read and refused on this measure: climate_action, states_federal_power,
  --   lands_keep_public, permitting_reform, enviro_balance. The argument against each is
  --   in db/vr-federal-mapping-seed-f1.json.
  --   BACKWARDS READ (rule 22), lands_energy: A NAY on H.J.Res. 131 is honestly described
  --   as opposition to 'Expand domestic energy, mining & resource development'. TRUE — the
  --   208 Democratic nays argued against opening the acreage and the 214 Republican yeas
  --   argued for it. Neither side would dispute the caption.
  --   BACKWARDS READ (rule 22), lands_preserve: A NAY on H.J.Res. 131 is honestly
  --   described as support for 'Protect public lands & wild places for future
  --   generations'. TRUE, and it is the nays' own stated argument.
  --   BACKWARDS READ (rule 22), energy_production: A NAY is honestly described as
  --   opposition to 'Unleash American oil, gas and nuclear to lower energy prices and
  --   boost independence'. TRUE for the oil-and-gas half, which is the half this
  --   resolution is about.
  --   BACKWARDS READ (rule 22), gov_regulation: A NAY is honestly described as opposition
  --   to 'Cut the number and cost of federal regulations'. TRUE at the mechanism level,
  --   and weighted at 60 precisely because the mechanism is a smaller share of what this
  --   vote was about than the acreage is.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_j_res_131, 'lands_energy', 100, true, 'yea_supports',
      'The resolution''s operative effect is on federal public land: it nullifies the Bureau of Land Management''s 2024-12-09 Record of Decision for the Coastal Plain oil and gas leasing programme, the decision that had made roughly 1.2 million of the programme area''s roughly 1.6 million acres unavailable for leasing and exploration. Striking it reopens that acreage. lands_energy is ''Expand domestic energy, mining & resource development'' and its keywords name ''oil'', ''gas'', ''drilling'', ''public land'' and ''extraction'' — the axis is public-land resource development, which is precisely what a leasing-availability decision is. Primary at 100 because it is the resolution''s whole subject: energy output is the consequence, and the acreage decision is the act. This is the record''s first federal lands_energy PRIMARY — the two prior federal rows are secondaries on packages, H.R. 26 at 45 and H.R. 1 at 40, which is exactly why the formal index could not read the axis for either Utah senator.',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/131'),
    (m_119_h_j_res_131, 'lands_preserve', 90, false, 'yea_opposes',
      'The acreage the resolution reopens is inside the Arctic National Wildlife Refuge, and the 2024 ROD''s stated reason for withdrawing it was to protect and conserve resources and certain uses. A yea removes that protection. lands_preserve is ''Protect public lands & wild places for future generations'' and its keywords name ''conservation'', ''wilderness'' and ''blm''. Weight 90 and yea_opposes follow the H.J.Res. 78 precedent exactly, including its written note that the conservation key is used because the vocabulary has no dedicated wildlife or endangered-species key. Not primary: the instrument acts on a leasing programme, and the conservation loss is the same act read from the other side.',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/131'),
    (m_119_h_j_res_131, 'energy_production', 75, false, 'yea_supports',
      'The reopened acreage is, under current law, the part of the programme area with the highest hydrocarbon potential, and the programme it belongs to exists to lease, develop, produce and transport oil and gas. A yea enlarges the area available for that. Weighted 75 — above H.J.Res. 88 and H.J.Res. 89''s 70 on the same key, and the difference is textual per rule 25: those resolutions struck a Clean Air Act vehicle waiver and reach production only indirectly, through vehicle demand, whereas this one acts directly on an oil-and-gas leasing programme. Not primary, because lands_energy carries the public-land act itself.',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/131'),
    (m_119_h_j_res_131, 'gov_regulation', 60, false, 'yea_supports',
      'The instrument is a Congressional Review Act resolution of disapproval under chapter 8 of title 5: its mechanism is congressional nullification of an agency decision, and a yea removes a federal agency''s rule and bars a substantially similar one. gov_regulation''s August 2026 scope note names ''Congressional Review Act disapprovals'' first in its IN list, and its stated polarity — ''support = fewer and cheaper federal rules'' — makes a yea yea_supports. Weight 60 matches H.J.Res. 88 and H.J.Res. 89, the two live CRA precedents in the record. The same scope note is why this row is a secondary and not the primary: what a particular rule should SAY belongs to the sector''s key, which here is lands_energy.',
      'https://www.congress.gov/bill/119th-congress/house-joint-resolution/131')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

  -- H.R. 5408 (119th) — econ_workers yea_supports w100 PRIMARY
  --   One key, on purpose. The drafting bench offered three candidates and two of them
  --   (tech_balance, tech_innovation) were title-keyword accidents; four further axes were
  --   read by hand and refused. econ_workers carries the whole of what the 230-193 roll
  --   tested. See db/vr-federal-mapping-seed-f1.json for the six refusals.
  --   Read and refused on this measure: tech_balance, tech_innovation, econ_smallbiz,
  --   econ_growth, econ_balance, paid_leave. The argument against each is in
  --   db/vr-federal-mapping-seed-f1.json.
  --   BACKWARDS READ (rule 22), econ_workers: A NAY on the Faster Labor Contracts Act is
  --   honestly described as opposition to 'Raise the minimum wage and protect workers from
  --   exploitation.' Reads TRUE on the second clause and silent on the first, which is why
  --   the rationale rests where it does. The 192 Republican nays argued against compulsory
  --   arbitration and the timetable, which is an argument about how far federal worker
  --   protection should reach — the axis itself, not a different one.
  INSERT INTO vr_measure_issues (measure_id, issue_key, weight, is_primary, support_meaning, rationale, source_url) VALUES
    (m_119_h_r_5408, 'econ_workers', 100, true, 'yea_supports',
      'The bill''s entire operative text is a first-contract bargaining regime: negotiations must begin within 10 days of a written request from a newly certified or recognised representative, either party may call in the Federal Mediation and Conciliation Service after 90 days without an agreement, FMCS must refer the dispute to binding arbitration if mediation fails within 30, the resulting agreement binds for two years, and the employer must hold wages, hours and conditions steady while bargaining continues. A yea creates federal protection for workers trying to reach a first contract. The chip names the minimum wage and this bill does not touch it, so the row rests on the chip''s second clause — ''protect workers from exploitation'' — and on the key''s own keyword list, which names ''collective bargaining'', ''union'' and ''labor''. The vocabulary declares this bill''s subject in scope. Weighted 100 and primary because it is the measure''s only subject: this is the record''s first federal econ_workers primary, the three prior federal rows being secondaries on packages (S. 129 at 60, H.R. 1319 at 45).',
      'https://www.congress.gov/bill/119th-congress/house-bill/5408')
  ON CONFLICT (measure_id, issue_key) DO NOTHING;

END $$;

-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------
-- Read-only, and scoped by tuple to exactly this pass's roll calls and measures so it
-- can only ever fail on data this migration is responsible for. A global count would
-- drag in every labour, lands and oversight mapping earlier passes wrote and stop
-- meaning anything.
--
-- Counts assert >= for member votes, because the one already-live roll holds votes an
-- earlier attribution path wrote, some of them possibly for members this roster does not
-- carry. The orphan check is therefore scoped to the 7 rolls this pass CREATED.
--
-- Five assertions are specific rather than aggregate, because they are the five things
-- this pass exists to do. Three name a PRIMARY mapping and its direction, one per
-- blocked key, so a row that landed on the wrong measure or with the wrong polarity is
-- caught rather than averaged into a total. The fourth asserts S.Amdt. 3535's parent_id
-- actually points at the FY2026 NDAA, since an amendment with a null parent renders
-- against nothing. The fifth asserts H.R. 1069 carries EXACTLY ZERO mapped rows — the
-- only way to make a deliberate refusal testable, and a tripwire for any later pass that
-- maps it without argument.
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  n_rolls integer;
  n_votes integer;
  n_orphan integer;
  n_issues integer;
  n_unmapped integer;
  n_parent integer;
  s_h_r_1069 text;
  s_s_j_res_18 text;
  n_gr_senate integer;
  n_congress_oversight_m_119_s_amdt_3535 integer;
  n_lands_energy_m_119_h_j_res_131 integer;
  n_econ_workers_m_119_h_r_5408 integer;
  n_house313 integer;
BEGIN
  WITH want (chamber, congress, session, roll_number) AS (VALUES
    ('house'::text, 119::integer, 1::integer, 71::integer),
    ('senate'::text, 119::integer, 1::integer, 151::integer),
    ('senate'::text, 119::integer, 1::integer, 153::integer),
    ('senate'::text, 119::integer, 1::integer, 563::integer),
    ('house'::text, 119::integer, 1::integer, 295::integer),
    ('house'::text, 119::integer, 1::integer, 313::integer),
    ('senate'::text, 119::integer, 1::integer, 632::integer),
    ('house'::text, 119::integer, 2::integer, 216::integer)
  ), roll_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN want w
      ON r.chamber = w.chamber AND r.congress = w.congress
     AND r.session = w.session AND r.roll_number = w.roll_number
  ), fresh (chamber, congress, session, roll_number) AS (VALUES
    ('senate'::text, 119::integer, 1::integer, 563::integer),
    ('house'::text, 119::integer, 1::integer, 295::integer),
    ('senate'::text, 119::integer, 1::integer, 632::integer),
    ('house'::text, 119::integer, 2::integer, 216::integer),
    ('house'::text, 119::integer, 1::integer, 71::integer),
    ('senate'::text, 119::integer, 1::integer, 151::integer),
    ('senate'::text, 119::integer, 1::integer, 153::integer)
  ), fresh_ids AS (
    SELECT r.id FROM vr_rollcalls r JOIN fresh f
      ON r.chamber = f.chamber AND r.congress = f.congress
     AND r.session = f.session AND r.roll_number = f.roll_number
  ), mine (measure_type, congress, chamber, number) AS (VALUES
    ('resolution'::text, 119::integer, 'house'::text, 'H.J.Res. 25'::text),
    ('resolution'::text, 119::integer, 'senate'::text, 'S.J.Res. 18'::text),
    ('bill'::text, 119::integer, 'house'::text, 'H.R. 1069'::text),
    ('amendment'::text, 119::integer, 'senate'::text, 'S.Amdt. 3535'::text),
    ('resolution'::text, 119::integer, 'house'::text, 'H.J.Res. 131'::text),
    ('bill'::text, 119::integer, 'house'::text, 'H.R. 5408'::text)
  ), measure_ids AS (
    SELECT m.id FROM vr_measures m JOIN mine k
      ON m.measure_type = k.measure_type AND m.congress = k.congress
     AND m.chamber = k.chamber AND m.number = k.number
  )
  SELECT (SELECT count(*) FROM roll_ids),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM roll_ids)),
         (SELECT count(*) FROM vr_member_votes v WHERE v.rollcall_id IN (SELECT id FROM fresh_ids)
            AND v.politician_id NOT IN (
              'adam_smith', 'aguilar', 'alsobrooks', 'andy_harris', 'andy_kim', 'angie_craig', 'angus_king', 'aoc', 'arrington', 'ashley_moody', 'ayanna_pressley', 'banks', 'barrasso', 'bennet', 'bennie_thompson', 'blackburn', 'blumenthal', 'blunt_rochester', 'bmoore', 'boebert', 'booker', 'boozman', 'brendan_boyle', 'brian_babin', 'brian_mast', 'britt', 'bruce_westerman', 'bryan_steil', 'cantwell', 'capito', 'cassidy', 'chellie_pingree', 'chip_roy', 'chris_murphy', 'clyburn', 'collins', 'comer', 'coons', 'cortez_masto', 'cotton', 'crapo', 'crockett', 'cruz', 'cstewart', 'curtis', 'daines', 'dan_crenshaw', 'dan_goldman', 'dan_sullivan', 'deb_fischer', 'debbie_dingell', 'delauro', 'delia_ramirez', 'diana_degette', 'don_bacon', 'don_davis', 'donalds', 'duckworth', 'durbin', 'emmer', 'ernst', 'fetterman', 'fitzpatrick', 'foxx', 'frank_lucas', 'french_hill', 'gaetz', 'gallego', 'garbarino', 'gillibrand', 'glenn_thompson', 'graham', 'grassley', 'greg_landsman', 'guthrie', 'hagerty', 'haley_stevens', 'hawley', 'heinrich', 'hickenlooper', 'hirono', 'hoeven', 'jake_auchincloss', 'jan_schakowsky', 'jared_golden', 'jared_huffman', 'jason_smith', 'jayapal', 'jeffries', 'jerry_moran', 'jim_himes', 'jim_jordan', 'jim_justice', 'jim_mcgovern', 'john_cornyn', 'jon_ossoff', 'josh_brecheen', 'josh_gottheimer', 'julie_fedorchak', 'kaine', 'kclark', 'kennedy', 'kennedy_john', 'kevin_cramer', 'kevin_hern', 'khanna', 'klobuchar', 'lankford', 'lee', 'lujan', 'lummis', 'luna', 'maggie_hassan', 'maloy', 'mariannette_miller_meeks', 'marie_gluesenkamp_perez', 'mark_kelly', 'markey', 'massie', 'maxine_waters', 'maxwell_frost', 'mcclain', 'mcconnell', 'mccormick', 'meeks', 'merkley', 'michael_guest', 'mike_bost', 'mike_collins', 'mike_ezell', 'mike_flood', 'mike_johnson', 'mike_lawler', 'mike_rounds', 'mike_simpson', 'mike_waltz', 'moreno', 'mtg', 'mullin', 'murkowski', 'murray', 'nadler', 'nancy_mace', 'neal', 'neguse', 'omar', 'owens', 'padilla', 'pallone', 'peters', 'raja_krishnamoorthi', 'rand_paul', 'raskin', 'reed', 'rick_crawford', 'rick_larsen', 'rick_scott', 'ricketts', 'risch', 'rob_bresnahan', 'robert_garcia', 'roger_marshall', 'roger_williams', 'ron_johnson', 'rosen', 'rubio', 'ryan_mackenzie', 'sam_graves', 'sanders', 'sarah_mcbride', 'scalise', 'schatz', 'schiff', 'schmitt', 'schumer', 'scott_perry', 'seth_moulton', 'shaheen', 'sheehy', 'slotkin', 'stefanik', 'steny_hoyer', 'stephanie_bice', 'steve_womack', 'summer_lee', 'takano', 'tammy_baldwin', 'ted_budd', 'ted_lieu', 'tgabbard', 'thune', 'tillis', 'tim_scott', 'tina_smith', 'tlaib', 'todd_young', 'tom_cole', 'tom_suozzi', 'tommy_tuberville', 'torres', 'trent_kelly', 'troy_downing', 'van_hollen', 'walberg', 'warner', 'warnock', 'warren', 'welch', 'whitehouse', 'wicker', 'wyden', 'zeldin', 'zoe_lofgren'
            )),
         (SELECT count(*) FROM vr_measure_issues i WHERE i.measure_id IN (SELECT id FROM measure_ids)
            AND i.issue_key IN ('audit_spending', 'congress_oversight', 'econ_corp_account', 'econ_workers', 'energy_production', 'gov_regulation', 'lands_energy', 'lands_preserve', 'tech_innovation'))
    INTO n_rolls, n_votes, n_orphan, n_issues;

  SELECT count(*) INTO n_congress_oversight_m_119_s_amdt_3535 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'amendment' AND m.congress = 119 AND m.chamber = 'senate'
     AND m.number = 'S.Amdt. 3535' AND i.issue_key = 'congress_oversight'
     AND i.is_primary AND i.support_meaning = 'yea_supports';
  SELECT count(*) INTO n_lands_energy_m_119_h_j_res_131 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'resolution' AND m.congress = 119 AND m.chamber = 'house'
     AND m.number = 'H.J.Res. 131' AND i.issue_key = 'lands_energy'
     AND i.is_primary AND i.support_meaning = 'yea_supports';
  SELECT count(*) INTO n_econ_workers_m_119_h_r_5408 FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house'
     AND m.number = 'H.R. 5408' AND i.issue_key = 'econ_workers'
     AND i.is_primary AND i.support_meaning = 'yea_supports';
  SELECT count(*) INTO n_unmapped FROM vr_measure_issues i JOIN vr_measures m ON m.id = i.measure_id
   WHERE m.measure_type = 'bill' AND m.congress = 119 AND m.chamber = 'house' AND m.number = 'H.R. 1069';
  SELECT status INTO s_h_r_1069 FROM vr_measures
   WHERE measure_type = 'bill' AND congress = 119 AND chamber = 'house' AND number = 'H.R. 1069';
  SELECT status INTO s_s_j_res_18 FROM vr_measures
   WHERE measure_type = 'resolution' AND congress = 119 AND chamber = 'senate' AND number = 'S.J.Res. 18';
  SELECT count(*) INTO n_gr_senate FROM vr_rollcalls r
    JOIN vr_measure_issues i ON i.measure_id = r.measure_id
   WHERE r.chamber = 'senate' AND i.issue_key = 'gov_regulation' AND i.is_primary;
  SELECT count(*) INTO n_parent FROM vr_measures child JOIN vr_measures par ON par.id = child.parent_id
   WHERE child.measure_type = 'amendment' AND child.congress = 119 AND child.number = 'S.Amdt. 3535'
     AND par.measure_type = 'bill' AND par.congress = 119 AND par.number = 'S. 2296';
  SELECT count(*) INTO n_house313 FROM vr_member_votes v
    JOIN vr_rollcalls r ON r.id = v.rollcall_id
   WHERE r.chamber = 'house' AND r.congress = 119 AND r.session = 1
     AND r.roll_number = 313;

  RAISE NOTICE 'Federal depth F1: % roll calls, % member votes, % issue mappings', n_rolls, n_votes, n_issues;
  RAISE NOTICE 'Federal depth F1: H.R. 1069 carries % mapped issue row(s)', n_unmapped;
  RAISE NOTICE 'Federal depth F1: H.R. 1069 status reads ''%''', s_h_r_1069;
  RAISE NOTICE 'Federal depth F1: S.J.Res. 18 status reads ''%''', s_s_j_res_18;
  RAISE NOTICE 'Federal depth F1: % senate roll call(s) now sit on a measure carrying a gov_regulation PRIMARY mapping', n_gr_senate;
  RAISE NOTICE 'Federal depth F1: house 119/1 roll 313 (H.R. 1069) carries % attributed member votes', n_house313;

  IF n_rolls <> 8 THEN
    RAISE EXCEPTION 'Federal depth F1: expected 8 roll calls, found %', n_rolls;
  END IF;
  IF n_votes < 819 THEN
    RAISE EXCEPTION 'Federal depth F1: expected at least 819 member votes on these roll calls, found %', n_votes;
  END IF;
  IF n_orphan > 0 THEN
    RAISE EXCEPTION 'Federal depth F1: % member vote(s) on the rolls this pass created carry a politician_id outside db/vr-member-map.json', n_orphan;
  END IF;
  IF n_issues < 11 THEN
    RAISE EXCEPTION 'Federal depth F1: expected at least 11 issue mappings on this pass''s measures, found %', n_issues;
  END IF;
  IF n_congress_oversight_m_119_s_amdt_3535 <> 1 THEN
    RAISE EXCEPTION 'Federal depth F1: the congress_oversight PRIMARY yea_supports row on S.Amdt. 3535 (119th) did not land (found % row(s))', n_congress_oversight_m_119_s_amdt_3535;
  END IF;
  IF n_lands_energy_m_119_h_j_res_131 <> 1 THEN
    RAISE EXCEPTION 'Federal depth F1: the lands_energy PRIMARY yea_supports row on H.J.Res. 131 (119th) did not land (found % row(s))', n_lands_energy_m_119_h_j_res_131;
  END IF;
  IF n_econ_workers_m_119_h_r_5408 <> 1 THEN
    RAISE EXCEPTION 'Federal depth F1: the econ_workers PRIMARY yea_supports row on H.R. 5408 (119th) did not land (found % row(s))', n_econ_workers_m_119_h_r_5408;
  END IF;
  IF n_parent <> 1 THEN
    RAISE EXCEPTION 'Federal depth F1: S.Amdt. 3535 is not filed against S. 2296 — parent_id does not resolve to the parent bill (found % row(s))', n_parent;
  END IF;
  IF n_unmapped <> 0 THEN
    RAISE EXCEPTION 'Federal depth F1: H.R. 1069 is deliberately unmapped and now carries % issue row(s). See db/vr-federal-mapping-seed-f1.json before adding one.', n_unmapped;
  END IF;
  IF s_h_r_1069 <> 'passed_house' THEN
    RAISE EXCEPTION 'Federal depth F1: H.R. 1069 status is ''%'', expected ''passed_house''', s_h_r_1069;
  END IF;
  IF s_s_j_res_18 <> 'enacted' THEN
    RAISE EXCEPTION 'Federal depth F1: S.J.Res. 18 status is ''%'', expected ''enacted''', s_s_j_res_18;
  END IF;
  IF n_gr_senate < 2 THEN
    RAISE EXCEPTION 'Federal depth F1: the Senate holds only % decisive roll(s) on a gov_regulation PRIMARY measure. Below 2 the primary wall in stance-helpers.js reopens and 76 senators read as not-about-this-issue on a key they have voted four times.', n_gr_senate;
  END IF;
  IF n_house313 < 109 THEN
    RAISE EXCEPTION 'house 119/1 roll 313 (H.R. 1069) lost member votes — only % on file, expected at least 109', n_house313;
  END IF;
END $$;
